-- Fit Check: initial schema (PRD section 6.1).
-- Forward-only. Every table carries user_id and an RLS policy from day one so that
-- opening the app to more users later is adding rows, not rewriting policies.

create extension if not exists vector;
create extension if not exists pg_cron;

-- ---------------------------------------------------------------------------
-- Enums. Kept as Postgres enums (not check constraints) so the TypeScript types
-- generated by `supabase gen types` carry the unions.
-- ---------------------------------------------------------------------------
create type item_status as enum ('active', 'virtual', 'archived');
create type item_availability as enum ('home', 'laundry', 'away', 'lent');
create type item_source as enum ('photo', 'sheet', 'link', 'receipt');
create type context_type as enum ('weekday', 'shabbat', 'holiday', 'reserve', 'date', 'interview', 'event', 'trip');
create type context_source as enum ('hebcal', 'calendar', 'manual');
create type outfit_source as enum ('daily', 'manual', 'swap');
create type wear_feedback as enum ('worn', 'skipped', 'disliked');

-- ---------------------------------------------------------------------------
-- profile: one row per user. Body photo lives in the private bucket, only its path here.
-- ---------------------------------------------------------------------------
create table profile (
  user_id uuid primary key references auth.users (id) on delete cascade,
  height_cm int,
  shirt_size text,
  pants_w int,
  pants_l int,
  shoe_size numeric(4, 1),
  locale text not null default 'he',
  push_hour smallint not null default 7 check (push_hour between 0 and 23),
  push_token text,
  body_photo_path text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- items: the wardrobe. `tags` is the frozen JSON schema from packages/schema; the
-- hot columns are duplicated out of it for indexing and SQL filters.
-- ---------------------------------------------------------------------------
create table items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  external_id text,                       -- the sheet ID (e.g. "401"), kept for the import and pair weights
  name text not null,
  brand text,
  tags jsonb not null,
  category text not null,
  subcategory text not null,
  color_hex text not null,
  color_name text not null,
  pattern text not null,
  material text not null,
  formality smallint not null check (formality between 1 and 10),
  seasons text[] not null,
  temp_min_c smallint not null,
  temp_max_c smallint not null,
  modesty_flags text[] not null default '{}',
  status item_status not null default 'active',
  availability item_availability not null default 'home',
  source item_source not null,
  price numeric(10, 2),
  currency char(3),
  purchased_at date,
  original_path text,
  cutout_path text,
  thumb_path text,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint items_temp_range check (temp_min_c <= temp_max_c),
  constraint items_external_id_unique unique (user_id, external_id)
);
create index items_user_status_avail on items (user_id, status, availability);
create index items_user_category on items (user_id, category);

-- ---------------------------------------------------------------------------
-- item_vectors: FashionCLIP embeddings, 512-d. HNSW for cosine similarity.
-- ---------------------------------------------------------------------------
create table item_vectors (
  item_id uuid primary key references items (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  embedding vector(512) not null,
  model_version text not null,
  created_at timestamptz not null default now()
);
create index item_vectors_embedding_hnsw on item_vectors using hnsw (embedding vector_cosine_ops) with (m = 16, ef_construction = 64);

-- ---------------------------------------------------------------------------
-- outfits + outfit_items: what the engine proposed. Explanations stored in both
-- languages so the UI never re-calls the LLM to switch locale.
-- ---------------------------------------------------------------------------
create table outfits (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  context_type context_type not null,
  created_for_date date not null,
  score numeric(4, 3),
  breakdown jsonb,
  llm_explanation_he text,
  llm_explanation_en text,
  source outfit_source not null default 'daily',
  created_at timestamptz not null default now()
);
create index outfits_user_date on outfits (user_id, created_for_date desc);

create table outfit_items (
  outfit_id uuid not null references outfits (id) on delete cascade,
  item_id uuid not null references items (id) on delete cascade,
  slot text not null check (slot in ('top', 'bottom', 'shoes', 'layer')),
  primary key (outfit_id, item_id)
);

-- ---------------------------------------------------------------------------
-- wears: the feedback loop. One row per day the user answered the push.
-- ---------------------------------------------------------------------------
create table wears (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  outfit_id uuid references outfits (id) on delete set null,
  worn_on date not null,
  feedback wear_feedback not null,
  reason text,
  selfie_path text,
  created_at timestamptz not null default now()
);
create index wears_user_date on wears (user_id, worn_on desc);

-- ---------------------------------------------------------------------------
-- contexts: what kind of day it is. One row per (user, date, type); the daily job
-- reads the highest-priority row for the day.
-- ---------------------------------------------------------------------------
create table contexts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  date date not null,
  type context_type not null,
  source context_source not null,
  context_key text,                       -- e.g. the person's name for "date", used by no-repeat
  payload jsonb not null default '{}',
  created_at timestamptz not null default now(),
  unique (user_id, date, type)
);

-- ---------------------------------------------------------------------------
-- pair_weights: learned "these go together" scores. item_a < item_b enforced so a
-- pair has exactly one row.
-- ---------------------------------------------------------------------------
create table pair_weights (
  user_id uuid not null references auth.users (id) on delete cascade,
  item_a uuid not null references items (id) on delete cascade,
  item_b uuid not null references items (id) on delete cascade,
  weight numeric(4, 3) not null default 0 check (weight between -1 and 1),
  updated_at timestamptz not null default now(),
  primary key (user_id, item_a, item_b),
  constraint pair_weights_ordered check (item_a < item_b)
);

-- ---------------------------------------------------------------------------
-- context_rules: per-user overrides of the defaults in packages/engine/config.ts.
-- ---------------------------------------------------------------------------
create table context_rules (
  user_id uuid not null references auth.users (id) on delete cascade,
  type context_type not null,
  rules jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, type)
);

-- ---------------------------------------------------------------------------
-- v2 tables, created now so later migrations only add columns.
-- ---------------------------------------------------------------------------
create table wishlist (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  url text not null,
  title text,
  image_url text,
  size text,
  target_price numeric(10, 2),
  currency char(3),
  virtual_item_id uuid references items (id) on delete set null,
  created_at timestamptz not null default now()
);

create table price_history (
  id bigint generated always as identity primary key,
  wishlist_id uuid not null references wishlist (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  price numeric(10, 2) not null,
  currency char(3) not null,
  checked_at timestamptz not null default now()
);

create table receipts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  gmail_message_id text,
  merchant text,
  purchased_at date,
  raw_json jsonb,
  processed boolean not null default false,
  created_at timestamptz not null default now(),
  unique (user_id, gmail_message_id)
);

-- ---------------------------------------------------------------------------
-- ai_calls: every AI call, with cost. Cost visibility is a feature.
-- ---------------------------------------------------------------------------
create table ai_calls (
  id bigint generated always as identity primary key,
  user_id uuid references auth.users (id) on delete set null,
  provider text not null,                 -- anthropic | google | modal
  model text not null,
  task text not null,                     -- separate | cutout | embed | tag | style | receipt
  input_tokens int,
  output_tokens int,
  images int,
  cost_usd numeric(8, 5),
  latency_ms int,
  ok boolean not null,
  error text,
  created_at timestamptz not null default now()
);
create index ai_calls_created on ai_calls (created_at desc);

-- ---------------------------------------------------------------------------
-- RLS: owner-only on every user table.
-- ---------------------------------------------------------------------------
alter table profile enable row level security;
alter table items enable row level security;
alter table item_vectors enable row level security;
alter table outfits enable row level security;
alter table outfit_items enable row level security;
alter table wears enable row level security;
alter table contexts enable row level security;
alter table pair_weights enable row level security;
alter table context_rules enable row level security;
alter table wishlist enable row level security;
alter table price_history enable row level security;
alter table receipts enable row level security;
alter table ai_calls enable row level security;

create policy "own profile" on profile for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own items" on items for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own vectors" on item_vectors for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own outfits" on outfits for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own outfit items" on outfit_items for all
  using (exists (select 1 from outfits o where o.id = outfit_id and o.user_id = auth.uid()))
  with check (exists (select 1 from outfits o where o.id = outfit_id and o.user_id = auth.uid()));
create policy "own wears" on wears for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own contexts" on contexts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own pair weights" on pair_weights for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own context rules" on context_rules for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own wishlist" on wishlist for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own price history" on price_history for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own receipts" on receipts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
-- ai_calls are written by Edge Functions with the service role; the user may read their own.
create policy "read own ai calls" on ai_calls for select using (auth.uid() = user_id);

-- ---------------------------------------------------------------------------
-- updated_at trigger
-- ---------------------------------------------------------------------------
create or replace function set_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;
create trigger profile_updated_at before update on profile for each row execute function set_updated_at();
create trigger items_updated_at before update on items for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------
-- Storage buckets. `originals` private, `cutouts` public (served via CDN).
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public) values ('originals', 'originals', false) on conflict do nothing;
insert into storage.buckets (id, name, public) values ('cutouts', 'cutouts', true) on conflict do nothing;

create policy "own originals" on storage.objects for all
  using (bucket_id = 'originals' and auth.uid()::text = (storage.foldername(name))[1])
  with check (bucket_id = 'originals' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "own cutouts write" on storage.objects for insert
  with check (bucket_id = 'cutouts' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "cutouts public read" on storage.objects for select using (bucket_id = 'cutouts');

-- ---------------------------------------------------------------------------
-- Similar-item search for the pre-purchase duplicate check (PRD 4.5).
-- ---------------------------------------------------------------------------
create or replace function match_items(query_embedding vector(512), match_threshold float, match_count int)
returns table (item_id uuid, similarity float)
language sql stable
as $$
  select v.item_id, 1 - (v.embedding <=> query_embedding) as similarity
  from item_vectors v
  join items i on i.id = v.item_id
  where v.user_id = auth.uid()
    and i.status = 'active'
    and 1 - (v.embedding <=> query_embedding) > match_threshold
  order by v.embedding <=> query_embedding
  limit match_count;
$$;
